CREATE OR REPLACE FUNCTION public.axen_coin_test_cleanup(_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_uid AND email LIKE 'coin-test-%@example.com') THEN RAISE EXCEPTION 'temporary test account only'; END IF; ALTER TABLE public.contract_events DISABLE TRIGGER USER; ALTER TABLE public.proof_submissions DISABLE TRIGGER USER; ALTER TABLE public.contract_sessions DISABLE TRIGGER USER; ALTER TABLE public.daily_contracts DISABLE TRIGGER USER; DELETE FROM public.contract_events WHERE user_id=_uid; DELETE FROM public.proof_submissions WHERE user_id=_uid; DELETE FROM public.contract_sessions WHERE user_id=_uid; DELETE FROM public.daily_contracts WHERE user_id=_uid; ALTER TABLE public.contract_events ENABLE TRIGGER USER; ALTER TABLE public.proof_submissions ENABLE TRIGGER USER; ALTER TABLE public.contract_sessions ENABLE TRIGGER USER; ALTER TABLE public.daily_contracts ENABLE TRIGGER USER; END; $$; REVOKE ALL ON FUNCTION public.axen_coin_test_cleanup(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.axen_coin_test_cleanup(uuid) TO service_role;